func update(visibleFrom positions: [(CGPoint, CGFloat)]) {
    // Reset all visible to explored
    for y in 0..<mapHeight {
        for x in 0..<mapWidth {
            if fogState[y][x] == 2 {
                fogState[y][x] = 1  // visible -> explored
            }
        }
    }

    // Mark tiles in vision range as visible
    for (position, visionRange) in positions {
        let centerTile = worldToTile(position)
        let tileRange = Int(ceil(visionRange / tileSize))

        for dy in -tileRange...tileRange {
            for dx in -tileRange...tileRange {
                let tx = centerTile.x + dx
                let ty = centerTile.y + dy
                guard tx >= 0, tx < mapWidth, ty >= 0, ty < mapHeight else { continue }

                let tileCenter = tileToWorld(tx, ty)
                let distance = position.distance(to: tileCenter)
                if distance <= visionRange {
                    fogState[ty][tx] = 2  // visible
                    updateTileVisual(x: tx, y: ty)
                }
            }
        }
    }
}
