// Create fog tiles in FogOfWar init
for y in 0..<mapHeight {
    for x in 0..<mapWidth {
        let tile = SKSpriteNode(color: .black, size: CGSize(width: tileSize, height: tileSize))
        tile.position = CGPoint(x: CGFloat(x) * tileSize + tileSize/2, 
                                y: CGFloat(y) * tileSize + tileSize/2)
        tile.alpha = 1.0  // Start unexplored
        fogNode.addChild(tile)
        fogTiles[y][x] = tile
    }
}

// Update fog tile alpha based on state
func updateTileVisual(x: Int, y: Int) {
    switch fogState[y][x] {
    case 0: fogTiles[y][x]?.alpha = 1.0   // unexplored
    case 1: fogTiles[y][x]?.alpha = 0.5   // explored
    case 2: fogTiles[y][x]?.alpha = 0.0   // visible
    }
}
